import React from 'react';

import clsx from 'clsx';

import style from './style.module.less';

const EquipOptionsWidget: React.FC<{ weight: number; value: number; className?: string }> = ({
  weight,
  value,
  className,
}) => (
  <div className={clsx('text-end me-2', className, style.eow)}>
    <div className="border-bottom text-nowrap">
      <b>{weight}</b>&thinsp;кг
    </div>
    <div className="text-nowrap">
      <b>{value}</b>&thinsp;л&nbsp;
    </div>
  </div>
);

export default EquipOptionsWidget;
